Ext.define('Spt_Sp_JoinPublicAnnouncement.view.JoinPublicAnnounceViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.Spt_Sp_JoinPublicAnnouncementjoinpublicannounce',

    showList: function() {
        var me = this;
        list = me.lookupReference('joinPublicAnnounceList');
        me.getView().setActiveItem(list);
    },

    onPanelShowBidDetail: function(id, purchaseType, inOutType, foreignBidType, distributionElecPrivateYN, eventOptions) {
        var me = this,
            view = me.getView();
        var detail = "";

        if( purchaseType == 'ProductBid'){
            if(foreignBidType == 'ProductBidForeignItem' || foreignBidType == 'ProductBidSideEquipment'){ //외자
                detail = me.lookupReference('foreignProductBidAnnouncementDetail');
            }else{
                detail = me.lookupReference('productBidAnnouncementDetail');
            }
        }else{
            if(foreignBidType == 'ServiceBid'){ //외자
                detail = me.lookupReference('foreignServiceBidAnnouncementDetail');
            }else if(distributionElecPrivateYN == 'Y'){ //배전전자공개수의
                detail = me.lookupReference('DistributionElecPrivateDetail');
            }else{
                detail = me.lookupReference('serviceBidAnnouncementDetail');
            }
        }
        detail.setHiddenKepcoPanel(true);
        view.getLayout().setActiveItem(detail);
        detail.loadData(id, 'Bid');
    },

    onPanelShowReverseAuctionDetail: function(id,vendorAttendId, eventOptions) {
        var me = this;
        var detail = me.lookupReference('reverseAuctionDetail');
        detail.loadData(id, vendorAttendId);
        me.getView().getLayout().setActiveItem(detail);
    }

});
